(function(root){
'use strict';
const R=(text,plain=false)=>({t:'r',text,plain});
const N=x=>typeof x==='string'?R(x):x;
const S=(...nodes)=>({t:'seq',nodes:nodes.flat().map(N)});
const F=(num,den)=>({t:'frac',num:N(num),den:N(den)});
const SUB=(base,sub)=>({t:'sub',base:N(base),sub:N(sub)});
const SUP=(base,pow)=>({t:'sup',base:N(base),pow:N(pow)});
const mf=SUB('m','f'), mh=SUB('m','h'), C0=SUB('C','0'), K0=SUB('K','0');
const f0=SUB('f',C0),h0=SUB('h',K0),T=R('tan',true),L=R('ln',true),At=R('arctan',true);
const eq=(alt,ast,color='',emphasis=false)=>({type:'eq',alt,ast,color,emphasis});
const text=value=>({type:'text',value});
const source={pisk:'Piskunov, N. (1977). Cálculo diferencial e integral, tomo II. Mir. § 15, pp. 48–53.',esc:'Escobar A., J. (s. f.). Ecuaciones diferenciales con aplicaciones en Maple. Universidad de Antioquia. § 3.1.1, pp. 49–51.',clase:'Trujillo Salazar, C. A. (2026). ED 1.8. Apuntes del curso, Universidad del Quindío.',raup:'Raup, D. M. (1966). Geometric analysis of shell coiling: General problems. Journal of Paleontology, 40(5), 1178–1190.'};
const slides=[
{title:'Trayectorias isogonales',kind:'cover',duration:15,body:[],notes:'Presentar la pregunta: ¿cómo construir una familia que corte a otra con un ángulo constante? Exposición de Ecuaciones Diferenciales. Docente: Carlos Andrés Trujillo Salazar. Duración sugerida: 20 minutos, incluida la animación de 95 segundos.'},
{title:'Dos familias monoparamétricas',kind:'theory',duration:45,action:0,body:[text('Una familia conocida y una familia que buscamos.'),eq('𝓕 = {f_C : C ∈ I}',S('𝓕 = {',SUB('f','C'),' : C ∈ I}'),'green'),eq('𝓗 = {h_K : K ∈ J}',S('𝓗 = {',SUB('h','K'),' : K ∈ J}'),'purple'),text('Cada curva queda determinada por un parámetro. Las mayúsculas nombran las familias y las minúsculas, sus curvas.')],notes:'I y J son los conjuntos de parámetros admitidos. Presentar la notación como la de un conjunto y sus elementos. El dibujo se construirá por etapas y conservará su posición mientras avanza la demostración.',source:'Piskunov, § 15. Escobar, § 3.1.1'},
{title:'Una curva de cada familia',kind:'theory',duration:45,body:[eq('f_C₀ ∈ 𝓕, h_K₀ ∈ 𝓗',S(f0,' ∈ 𝓕', '     ',h0,' ∈ 𝓗')),text('Fijamos los parámetros C₀ y K₀. En un entorno regular de P, escribimos las curvas como funciones de x.'),eq('f = f_C₀, h = h_K₀',S('f = ',f0,'     h = ',h0)),text('Usaremos f y h para aligerar la escritura.')],notes:'La representación y=f(x) o y=h(x) es local. En puntos con tangente vertical necesitaremos otra representación. Cero en C₀ y K₀ es un índice, no el valor numérico del parámetro.',source:'Notación del expositor'},
{title:'La curva conocida en P',kind:'theory',duration:35,action:1,body:[text('Elegimos un punto regular P sobre una curva de la familia conocida.'),eq('P = (x₀, y₀), y₀ = f(x₀)',S('P = (',SUB('x','0'),', ',SUB('y','0'),'),   ',SUB('y','0'),' = f(',SUB('x','0'),')'),'green'),text('La curva verde queda como referencia de la construcción.')],notes:'Mostrar la primera curva con el deslizador o con el botón. El diagrama usa un arco de círculo y una espiral que sí forman un par isogonal. Los valores concretos quedan en el esquema, sin ser necesarios para la prueba general.',source:'Construcción geométrica propia'},
{title:'La curva buscada por P',kind:'theory',duration:35,action:2,body:[text('Buscamos una curva de la segunda familia que también pase por P.'),eq('h(x₀) = f(x₀) = y₀',S('h(',SUB('x','0'),') = f(',SUB('x','0'),') = ',SUB('y','0')),'purple'),text('La condición isogonal exige el mismo ángulo entre tangentes en cada intersección regular.')],notes:'Compartir P no basta para ser isogonal. La condición debe cumplirse en todas las intersecciones regulares con la familia dada. γ mide un ángulo de rectas, que se entiende módulo π.',source:'Piskunov, § 15. Escobar, Definición 3.1'},
{title:'Las tangentes y sus pendientes',kind:'theory',duration:55,action:3,body:[text('La derivada determina la pendiente de la tangente.'),eq('m_f = f′(x₀) = tan α',S(mf,' = f′(',SUB('x','0'),') = ',T,' α'),'green'),eq('m_h = h′(x₀) = tan β',S(mh,' = h′(',SUB('x','0'),') = ',T,' β'),'purple'),text('α y β son las inclinaciones respecto del eje horizontal positivo.')],notes:'Las pendientes pueden ser negativas aunque los ángulos de inclinación se tomen entre 0 y π. En el dibujo, α=135° y β=55°. Primero mostrar las tangentes y después los arcos angulares.',source:'Piskunov, § 15. Apuntes del expositor'},
{title:'El ángulo exterior del triángulo',kind:'theory',duration:75,action:4,body:[text('Las tangentes y el eje horizontal forman el triángulo BPA. α es exterior en A. β y γ son los interiores no adyacentes.'),eq('α = β + γ',S('α = β + γ'),'orange',true),text('Por el teorema del ángulo exterior:'),eq('γ = α − β',S('γ = α − β'),'orange'),text('En el esquema: 135° = 55° + 80°.')],notes:'Señalar el triángulo BPA: B está en la tangente morada y A en la verde. α se mide entre el rayo horizontal hacia la derecha y A→P. β está en B y γ en P. α coincide con la inclinación de la tangente verde porque usamos direcciones paralelas. Esta configuración ilustra la relación orientada; otras configuraciones se tratan módulo π.',source:'Teorema del ángulo exterior. Construcción propia'},
{title:'La relación entre las pendientes',kind:'theory',duration:55,body:[eq('tan γ = tan(α − β)',S(T,' γ = ',T,'(α − β)')),eq('tan γ = (tan α − tan β)/(1 + tan α tan β)',S(T,' γ = ',F(S(T,' α − ',T,' β'),S('1 + ',T,' α ',T,' β')))),eq('tan γ = (m_f − m_h)/(1 + m_f m_h)',S(T,' γ = ',F(S(mf,' − ',mh),S('1 + ',mf,' ',mh))),'orange',true)],notes:'Aplicar la identidad de la tangente de una diferencia. La igualdad se usa donde los denominadores están definidos. Para el caso ortogonal evitaremos tan(90°). El ángulo no orientado es el valor agudo entre rectas.',source:'Piskunov, § 15. Escobar, § 3.1.1'},
{title:'La EDO de la familia conocida',kind:'theory',duration:60,body:[text('Partimos de una ecuación implícita de la familia.'),eq('F(x, y, C) = 0',S('F(x, y, C) = 0'),'green'),eq('F_x + F_y m_f = 0',S(SUB('F','x'),' + ',SUB('F','y'),' ',mf,' = 0')),text('Derivamos con C fijo y eliminamos el parámetro.'),eq('E(x, y, m_f) = 0',S('E(x, y, ',mf,') = 0'),'green',true)],notes:'F es una ecuación que representa la familia 𝓕. E nombra su ecuación diferencial asociada. La eliminación del parámetro requiere las hipótesis locales habituales. Si la familia ya está en forma y=f_C(x), se deriva y se elimina C directamente.',source:'Piskunov, § 15. Escobar, § 3.1.1'},
{title:'La pendiente de la trayectoria',kind:'theory',duration:80,body:[eq('tan γ (1 + m_f m_h) = m_f − m_h',S(T,' γ (1 + ',mf,' ',mh,') = ',mf,' − ',mh)),eq('m_h (1 + m_f tan γ) = m_f − tan γ',S(mh,' (1 + ',mf,' ',T,' γ) = ',mf,' − ',T,' γ')),eq('m_h = (m_f − tan γ)/(1 + m_f tan γ)',S(mh,' = ',F(S(mf,' − ',T,' γ'),S('1 + ',mf,' ',T,' γ'))),'purple',true)],notes:'Despejar m_h paso a paso y conservar a la vista la misma construcción. La relación fija γ=α−β. El denominador cero corresponde a una tangente vertical, no a que la geometría desaparezca.',source:'Deducción del expositor a partir de Piskunov y Escobar'},
{title:'La EDO de la familia buscada',kind:'theory',duration:85,body:[text('Para sustituir en E, despejamos la pendiente conocida.'),eq('m_f = (m_h + tan γ)/(1 − m_h tan γ)',S(mf,' = ',F(S(mh,' + ',T,' γ'),S('1 − ',mh,' ',T,' γ'))),'green'),text('En la familia buscada, m_h = y′.'),eq('E(x, y, (y′ + tan γ)/(1 − y′ tan γ)) = 0',S('E(x, y, ',F(S('y′ + ',T,' γ'),S('1 − y′ ',T,' γ')),') = 0'),'purple',true),text('Al resolver esta EDO obtenemos las trayectorias isogonales.')],notes:'La sustitución dentro de E usa m_f expresada en términos de m_h. Si se sustituye directamente la expresión para m_h dentro de una EDO que espera m_f, se invierte el sentido de la transformación. Recordar que y′ ahora pertenece a la familia buscada.',source:'Piskunov, § 15. Escobar, § 3.1.1'},
{title:'Caso ortogonal y alcance local',kind:'theory',duration:45,body:[text('Cuando γ = 90°, las tangentes son perpendiculares.'),eq('m_f m_h = −1',S(mf,' ',mh,' = −1'),'orange',true),eq('m_h = −1/m_f',S(mh,' = −',F('1',mf))),text('Usamos el producto de pendientes porque tan(90°) no está definida.'),text('Las fórmulas con pendientes finitas se aplican localmente. Las tangentes verticales requieren otra representación.')],notes:'Conectar con el tema de ED 1.8. El producto −1 aplica cuando ambas pendientes son finitas y la conocida es no nula. Las horizontales y verticales también pueden ser perpendiculares aunque el producto no esté definido.',source:'Trujillo Salazar, ED 1.8. Piskunov, § 15'},
{title:'Ejemplo 1: una familia hiperbólica',kind:'example',graph:'hyperbola',duration:60,body:[eq('y(x + C) = 1',S('y(x + C) = 1'),'green'),eq('m_f = −y²',S(mf,' = −',SUP('y','2')),'green'),text('Buscamos trayectorias con γ = 45°.'),eq('y′ = (y² + 1)/(y² − 1)',S('y′ = ',F(S(SUP('y','2'),' + 1'),S(SUP('y','2'),' − 1'))),'purple',true)],notes:'Fuente: ejemplo de Escobar, sección 3.1.1. Derivar y(x+C)=1: y′(x+C)+y=0. Como x+C=1/y y y≠0, m_f=−y². Aplicar la fórmula con tan45°=1. El ejemplo usa la orientación del esquema.',source:'Escobar, § 3.1.1, pp. 49–51'},
{title:'Integración de la trayectoria',kind:'example',graph:'hyperbola',duration:60,body:[eq('dx/dy = (y² − 1)/(y² + 1)',S(F('dx','dy'),' = ',F(S(SUP('y','2'),' − 1'),S(SUP('y','2'),' + 1')))),eq('dx/dy = 1 − 2/(1 + y²)',S(F('dx','dy'),' = 1 − ',F('2',S('1 + ',SUP('y','2'))))),eq('y − 2 arctan y = x + K',S('y − 2 ',At,' y = x + K'),'purple',true),text('La representación x = x(y) incluye los puntos donde la tangente es vertical.')],notes:'Invertir la derivada en los intervalos donde sea válido y luego prolongar la solución implícita. En y=±1, dx/dy=0 y la tangente es vertical. La curva original tiene y≠0. Distinguir las restricciones de la forma explícita y de la curva implícita.',source:'Escobar, § 3.1.1, pp. 49–51'},
{title:'Verificación en P = (0, 2)',kind:'example',graph:'hyperbola-check',duration:45,body:[eq('C = 1/2, K = 2 − 2 arctan 2',S('C = ',F('1','2'),',   K = 2 − 2 ',At,' 2')),eq('m_f = −4, m_h = 5/3',S(mf,' = −4,   ',mh,' = ',F('5','3'))),eq('|(m_f − m_h)/(1 + m_f m_h)| = 1',S('|',F(S(mf,' − ',mh),S('1 + ',mf,' ',mh)),'| = 1'),'orange',true),text('Las curvas pasan por P y el ángulo agudo entre tangentes es 45°.')],notes:'El cociente orientado también vale +1. α≈104.04° y β≈59.04°, diferencia45°. La gráfica verde usa C=1/2 y la morada K=2−2arctan2. En el dibujo las tangentes confirman el cálculo.',source:'Cálculo y gráfica propios. Familia de Escobar'},
{title:'Ejemplo 2: rectas radiales',kind:'example',graph:'rays',duration:60,body:[eq('y = Cx, m_f = y/x',S('y = Cx,   ',mf,' = ',F('y','x')),'green'),text('Aquí elegimos la orientación de Piskunov: β = α + γ. Tomamos k = tan γ > 0.'),eq('y′ = (y + kx)/(x − ky)',S('y′ = ',F('y + kx','x − ky')),'purple',true),text('La orientación opuesta se obtiene cambiando γ por −γ.')],notes:'Explicitar el cambio de orientación evita confundir signos. La fórmula anterior tenía γ=α−β. Aquí la tangente de la trayectoria gira en sentido positivo respecto de la recta radial. El ejemplo de Piskunov produce espirales logarítmicas.',source:'Piskunov, tomo II, § 15, pp. 51–53'},
{title:'La ecuación homogénea',kind:'example',duration:75,body:[eq('y = ux, y′ = u + x du/dx',S('y = ux,   y′ = u + x ',F('du','dx'))),eq('x du/dx = k(1 + u²)/(1 − ku)',S('x ',F('du','dx'),' = ',F(S('k(1 + ',SUP('u','2'),')'),'1 − ku'))),eq('(1 − ku)/(1 + u²) du = k dx/x',S(F('1 − ku',S('1 + ',SUP('u','2'))),' du = k ',F('dx','x'))),eq('arctan u − (k/2) ln(1 + u²) = k ln|x| + K',S(At,' u − ',F('k','2'),' ',L,'(1 + ',SUP('u','2'),') = k ',L,'|x| + K'),'purple',true)],notes:'Trabajar en x≠0 y en intervalos donde la separación está definida. Integrar du/(1+u²) y udu/(1+u²). La constante absorbe términos de la transformación posterior. arctan fija una rama local del ángulo.',source:'Piskunov, tomo II, § 15, pp. 51–53'},
{title:'La espiral logarítmica',kind:'example',graph:'spiral',duration:60,body:[eq('x = r cos θ, y = r sin θ',S('x = r ',R('cos',true),' θ,   y = r ',R('sin',true),' θ')),eq('ln r = θ/k + K',S(L,' r = ',F('θ','k'),' + K')),eq('r = A e^(θ cot γ), A > 0',S('r = A ',SUP('e',S('θ ',R('cot',true),' γ')),',   A > 0'),'purple',true),eq('tan γ = r/(dr/dθ)',S(T,' γ = ',F('r',F('dr','dθ'))),'orange'),text('θ se mide en radianes. El radio y la tangente conservan el ángulo γ.')],notes:'Usar 1+u²=r²/x² y θ=arctan u en una rama local. La expresión polar prolonga la espiral más allá de esa rama. La verificación tanγ=r/(dr/dθ) usa las componentes radial y angular del vector tangente.',source:'Piskunov, § 15. Deducción propia'},
{title:'El ángulo constante en movimiento',kind:'video',duration:95,body:[text('Rectas radiales y espirales logarítmicas con γ = 80°.')],notes:'Reproducir la animación propia completa de95 segundos. Señalar el radio, la tangente y la conservación del ángulo mientras se mueve el punto. El video no tiene audio, lo que permite explicarlo durante la reproducción.',source:'Animación original del expositor, 95 segundos'},
{title:'Un modelo radial de crecimiento',kind:'example',graph:'biology',duration:75,body:[eq('r(θ) = r₀ W^(θ/(2π))',S('r(θ) = ',SUB('r','0'),' ',SUP('W',F('θ','2π'))),'purple',true),eq('b = ln W/(2π), r = r₀ e^(bθ)',S('b = ',F(S(L,' W'),'2π'),',   r = ',SUB('r','0'),' ',SUP('e','bθ'))),text('W es el factor de expansión por vuelta. Si W es constante, el perfil radial es una espiral logarítmica.'),text('Ilustración: r₀ = 10 mm y W = 2. Tras 0, 1 y 2 vueltas: 10, 20 y 40 mm.')],notes:'Raup1966 desarrolla un modelo geométrico de enrollamiento de conchas con varios parámetros. Aquí mostramos únicamente su componente de expansión radial. W=2 es una ilustración matemática, no mediciones de un organismo. b=ln2/(2π)≈0.1103 y el ángulo radio-tangente≈83.7°. No afirmar que toda concha sigue este modelo ni que se trata de la espiral áurea.',source:'Raup (1966), pp. 1179–1181. Valores ilustrativos'},
{title:'La construcción y la ecuación',kind:'recap',duration:20,body:[text('La geometría fija la relación entre las pendientes.'),eq('m_h = (m_f − tan γ)/(1 + m_f tan γ)',S(mh,' = ',F(S(mf,' − ',T,' γ'),S('1 + ',mf,' ',T,' γ'))),'purple',true),text('La EDO asociada permite construir la familia buscada. Para rectas radiales, las trayectorias son espirales logarítmicas.')],notes:'Recuperar la idea central y permitir volver al diagrama con el índice si hay preguntas. No añadir nuevos resultados.',source:'Piskunov, § 15. Escobar, § 3.1.1'},
{title:'Referencias',kind:'references',duration:20,body:[],notes:'Referencias principales: Piskunov para el desarrollo de trayectorias isogonales y el ejemplo radial. Escobar para el ejemplo hiperbólico. Los apuntes ED1.8 conectan con trayectorias ortogonales. Raup sustenta el ejemplo biomatemático. Las gráficas y animación son del expositor.'},
{title:'Gracias',kind:'closing',duration:0,body:[],notes:'Espacio para preguntas después de los20 minutos de exposición.'}
];
const clamp=(value,max)=>Math.max(0,Math.min(max,Number.isFinite(Number(value))?Math.round(Number(value)):0));
function initial(saved){return {slide:clamp(saved?.slide,slides.length-1),phase:clamp(saved?.phase,4)};}
function transition(state,action){
 const next={...state};
 if(action.type==='navigate')next.slide=clamp(state.slide+action.delta,slides.length-1);
 if(action.type==='go')next.slide=clamp(action.slide,slides.length-1);
 if(action.type==='phase')next.phase=clamp(action.phase,4);
 return next;
}
const degrees=x=>x*180/Math.PI;
const beta=55*Math.PI/180, alpha=135*Math.PI/180, gamma=80*Math.PI/180;
const geometry={P:[3,3],A:[6,0],B:[3-3/Math.tan(beta),0],mf:-1,mh:Math.tan(beta),alpha,beta,gamma,b:1/Math.tan(10*Math.PI/180)};
const knownPoints=Array.from({length:160},(_,i)=>{const x=.15+4.075*i/159;return [x,Math.sqrt(18-x*x)];});
const soughtPoints=Array.from({length:180},(_,i)=>{const t=Math.PI/4-.30+.4*i/179,r=Math.sqrt(18)*Math.exp(geometry.b*(t-Math.PI/4));return [r*Math.cos(t),r*Math.sin(t)];});
const api={slides,source,initial,transition,geometry,knownPoints,soughtPoints,degrees};
if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.PresentationModel=api;
})(typeof globalThis==='undefined'?this:globalThis);
